import org.apache.commons.lang3.text.ExtendedMessageFormat;
import org.apache.commons.lang3.text.FormatFactory;
import java.text.Format;
import java.text.FieldPosition;
import java.text.ParsePosition;
import java.util.*;

public class Explore {
    static class UpperFormat extends Format {
        public StringBuffer format(Object obj, StringBuffer toAppendTo, FieldPosition pos) {
            return toAppendTo.append(String.valueOf(obj).toUpperCase());
        }
        public Object parseObject(String source, ParsePosition pos) { return source; }
    }
    static class UpperFactory implements FormatFactory {
        public Format getFormat(String name, String args, Locale locale) {
            if ("upper".equals(name)) return new UpperFormat();
            return null;
        }
    }
    public static void main(String[] args) throws Exception {
        Map<String, FormatFactory> registry = new HashMap<String, FormatFactory>();
        registry.put("upper", new UpperFactory());

        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,upper} and {1,number,integer}", Locale.US, registry);
        System.out.println("format: [" + emf.format(new Object[]{"hello", 42}) + "]");
        System.out.println("toPattern: [" + emf.toPattern() + "]");

        ExtendedMessageFormat emf2 = new ExtendedMessageFormat("{ 0 , upper }", Locale.US, registry);
        System.out.println("toPattern spaced: [" + emf2.toPattern() + "]");
        System.out.println("format spaced: [" + emf2.format(new Object[]{"abc"}) + "]");

        ExtendedMessageFormat emf3 = new ExtendedMessageFormat("'{0}' literal", Locale.US, registry);
        System.out.println("literal format: [" + emf3.format(new Object[]{"x"}) + "]");
        System.out.println("literal toPattern: [" + emf3.toPattern() + "]");

        ExtendedMessageFormat emf4 = new ExtendedMessageFormat("{0}, {1}", Locale.US);
        System.out.println("simple toPattern: [" + emf4.toPattern() + "]");

        try {
            new ExtendedMessageFormat("'abc", registry);
        } catch (IllegalArgumentException e) {
            System.out.println("quote err: " + e.getMessage());
        }
        try {
            new ExtendedMessageFormat("{0", registry);
        } catch (IllegalArgumentException e) {
            System.out.println("unterminated fe err: " + e.getMessage());
        }
        try {
            new ExtendedMessageFormat("{a}", registry);
        } catch (IllegalArgumentException e) {
            System.out.println("bad index err: " + e.getMessage());
        }

        ExtendedMessageFormat a1 = new ExtendedMessageFormat("{0}", Locale.US, registry);
        ExtendedMessageFormat a2 = new ExtendedMessageFormat("{0}", Locale.US, registry);
        System.out.println("equals: " + a1.equals(a2) + " hashEq: " + (a1.hashCode()==a2.hashCode()));

        try {
            emf.setFormat(0, new UpperFormat());
        } catch (UnsupportedOperationException e) {
            System.out.println("setFormat UOE ok");
        }

        ExtendedMessageFormat nullLocaleEmf = new ExtendedMessageFormat("{0}", (Locale) null);
        System.out.println("nullLocale: " + nullLocaleEmf.getLocale() + " default: " + Locale.getDefault());
    }
}
EOF
